async function seedIsolatedMockChannel(page) {
  const rows = await sharedRows(page, 'channels')
  const template = rows[0] ?? {}
  const now = Date.now()
  const target = {
    ...template,
    id: 'ch_smoke_mock',
    name: 'Smoke Mock',
    protocol: 'mock',
    baseUrl: 'http://mock.local',
    enabled: true,
    order: 999,
    priority: 999,
    weight: 1,
    routeStrategy: 'priority',
    models: SMOKE_MOCK_MODELS,
    modelCache: SMOKE_MOCK_MODELS,
    modelMap: SMOKE_MOCK_MODEL_MAP,
    credentialRef: null,
    altCredentialRef: null,
    hasToken: false,
    hasAltToken: false,
    tokenTail: null,
    altTokenTail: null,
    lastTestAt: now,
    lastTestLatency: 0,
    createdAt: now,
  }
  await sharedPut(page, 'channels', target)
  for (const row of rows) {
    if (row.id === target.id || !row.enabled) continue
    await sharedPut(page, 'channels', { ...row, enabled: false })
  }
  /*
   * 设置页会持续挂着应用级连接，`networkidle` 在 CI / 长跑环境里可能永远不满足。
   * 这里要证明的是“渠道已写入并能被页面读回”，所以等 DOM 就绪 + 设置卡真正出现即可。
   */
  await page.reload({ waitUntil: 'domcontentloaded' })
  await page.locator('[data-settings-card]').waitFor({ state: 'visible', timeout: 20_000 })
  /*
   * 设置卡可见只证明页面挂载了，不证明 ChannelStore 已完成 hydrate。
   * 后续马上进入电商页时若渠道还没读回，会表现为“点生成什么也没发生”。
   * 用刚种下的稳定 id 等 UI 真正看见它，才算夹具就绪。
   */
  await page
    .locator(`[data-channel-id="${target.id}"]`)
    .waitFor({ state: 'visible', timeout: 20_000 })
  const after = await sharedRows(page, 'channels')
  const seeded = after.find((row) => row.id === target.id)
  return {
    verified: seeded?.enabled === true && seeded?.protocol === 'mock',
    pulled: seeded?.enabled === true,
    enabled: seeded?.enabled === true,
  }
}

